<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableWriteGateway;
use Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Connector\Pdo\TemplateVariablePdoConnector;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableSlide;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableCursor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariable;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class TemplateVariableWriteRepositoryAdapter implements TemplateVariableWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateVariablePdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(TemplateVariableRef $ref): ?TemplateVariable
    {
        return $this->conn->retrieveForUpdate(new TemplateVariableFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?TemplateVariableFilter $filter = null, ?TemplateVariableCursor $cursor = null): TemplateVariableSlide
    {
        $this->logDebug("List for update of Template variable on adapter ");
        $span = $this->startSpan("List for update of Template variable on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new TemplateVariableSlide(function (TemplateVariableSlide $slide, ?TemplateVariableCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new TemplateVariableCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(TemplateVariableFilter $filter): ?TemplateVariable
    {
        $this->logDebug("Retrieve for update of Template variable on adapter ");
        $span = $this->startSpan("Retrieve for update of Template variable on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(TemplateVariableFilter $filter): bool
    {
        $this->logDebug("Exists for update of Template variable on adapter ");
        $span = $this->startSpan("Exists for update of Template variable on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?TemplateVariableFilter $filter = null): int
    {
        $this->logDebug("Count for update of Template variable on adapter ");
        $span = $this->startSpan("Count for update of Template variable on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(TemplateVariable $entity, ?Closure $verify = null): TemplateVariable
    {
        $this->logDebug("Count for Template variable on adapter ");
        $span = $this->startSpan("Count for Template variable on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('template-variable', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(TemplateVariableRef $ref, TemplateVariable $entity): TemplateVariable
    {
        $this->logDebug("Count for Template variable on adapter ");
        $span = $this->startSpan("Count for Template variable on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('template-variable', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(TemplateVariable $entity): bool
    {
        $this->logDebug("Count for Template variable on adapter ");
        $span = $this->startSpan("Count for Template variable on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('template-variable', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByCode(string $code): ?TemplateVariable
    {
        $this->logDebug("Find on by code for Template variable on adapter");
        $span = $this->startSpan("Find on by code for Template variable on adapter");
        try {
            return $this->conn->retrieveForUpdate(new TemplateVariableFilter(code: $code));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByCodeAndTenant(string $code, TenantRef $tenant): ?TemplateVariable
    {
        $this->logDebug("Find on by code tenant for Template variable on adapter");
        $span = $this->startSpan("Find on by code tenant for Template variable on adapter");
        try {
            return $this->conn->retrieveForUpdate(new TemplateVariableFilter(codeAndTenant: TemplateVariableFilter::codeAndTenantFilter(code: $code, tenant: $tenant)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(TemplateVariable $entity): void
    {
        $this->logDebug("Count for Template variable on adapter ");
        $span = $this->startSpan("Count for Template variable on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
